from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]
    colors = [c for c in counts if c != bg]

    # Vertical marker bars on opposing left/right edges, with an interior seed.
    for marker in colors:
        runs = {0: [], w-1: []}
        for col in (0, w-1):
            r=0
            while r<h:
                if g[r][col] != marker:
                    r+=1; continue
                a=r
                while r<h and g[r][col] == marker: r+=1
                if r-a >= 2: runs[col].append((a,r))
        for la,lb in runs[0]:
            for ra,rb in runs[w-1]:
                if lb-la != rb-ra: continue
                for a,b,side,oa,ob in ((la,lb,'left',ra,rb),(ra,rb,'right',la,lb)):
                    dots=[(r,c) for r in range(a,b) for c in range(w) if g[r][c] not in (bg,marker)]
                    if not dots: continue
                    ink=Counter(g[r][c] for r,c in dots).most_common(1)[0][0]
                    active=set()
                    for r,c in dots:
                        active.add(r-a)
                        if side=='left':
                            for x in range(1,c): g[r][x]=ink
                        else:
                            for x in range(c+1,w-1): g[r][x]=ink
                        g[r][c]=4
                    for off in active:
                        rr=oa+off
                        # Fill the mirrored row, stopping before a marker on its far edge.
                        lo=1 if g[rr][0]==marker else 0
                        hi=w-1 if g[rr][w-1]==marker else w
                        for x in range(lo,hi):
                            if g[rr][x] != marker: g[rr][x]=ink
                    return g

    # Horizontal marker bars across opposing top/bottom edges cast vertical strokes.
    top=[c for c in range(w) if g[0][c] != bg]
    bottom=[c for c in range(w) if g[h-1][c] != bg]
    if len(top)>=2 and len(bottom)>=2:
        marker=g[0][top[0]]
        if all(g[0][c]==marker for c in top) and all(g[h-1][c]==marker for c in bottom):
            seeds=[(r,c) for r in range(1,h-1) for c in range(w) if g[r][c] not in (bg,marker)]
            if seeds:
                ink=Counter(g[r][c] for r,c in seeds).most_common(1)[0][0]
                for c in (max(top), max(bottom)):
                    for r in range(1,h-1):
                        g[r][c]=4 if g[r][c]==ink else ink
                return g
    return g
